-- ПЛОХО на больших смещениях: OFFSET 1000000 читает и выбрасывает миллион строк
SELECT * FROM orders ORDER BY created_at DESC OFFSET 1000000 LIMIT 50;

-- ХОРОШО: keyset (cursor) — O(log n), стабильный порядок без дублей и пропусков
SELECT * FROM orders
 WHERE (tenant_id, created_at, id) < ($1, $2, $3)   -- уже виденные значения
 ORDER BY created_at DESC, id DESC
 LIMIT 50;
-- курсор кодируется в base64 и возвращается в ответе API: { "nextCursor": "..." }

// Атомарный инкремент с лимитом: одна Redis-команда = нет гонок
const Lua = `
local cur = redis.call('INCR', KEYS[1])
if cur == 1 then redis.call('EXPIRE', KEYS[1], ARGV[1]) end
if cur > tonumber(ARGV[2]) then return 0 end
return 1`;
const allowed = await redis.eval(Lua, { keys: [`rl:${userId}`], arguments: ['60', '100'] });

// Кеш-aside с джиттером против cache stampede
async function getProfile(id: string) {
  const hit = await redis.get(`profile:${id}`);
  if (hit) return JSON.parse(hit);
  const profile = await db.loadProfile(id);
  const ttlSec = 300 + Math.floor(Math.random() * 60); // 300..360 c
  await redis.set(`profile:${id}`, JSON.stringify(profile), { EX: ttlSec });
  return profile;
}
